    return START_STICKY;
  }
  if (Intent.ACTION_MEDIA_BUTTON.equals(intent.getAction())) {
    @Nullable Uri uri = intent.getData();
    @Nullable MediaSession session = uri != null ? MediaSession.getSession(uri) : null;
    if (session == null) {
      ControllerInfo controllerInfo = ControllerInfo.createLegacyControllerInfo();
      session = onGetSession(controllerInfo);
      if (session == null) {
        return START_STICKY;
      }
      try {
        addSession(session);
      } catch (NullPointerException | UnsupportedOperationException | IllegalArgumentException | ClassCastException e) {
        // Handle the exception, possibly log it or take other corrective actions
        return START_STICKY;
      }
    }
    KeyEvent keyEvent = intent.getParcelableExtra(Intent.EXTRA_KEY_EVENT);
    if (keyEvent != null) {
      session.getSessionCompat().getController().dispatchMediaButtonEvent(keyEvent);
    }
  }
